    """
    Perform K-Means clustering on each set of (x, y) coordinates separately and
    determine the overall labels and centroids by averaging the individual results.

    Parameters:
    - data_sets (list): A list of data sets. Each data set may be either a
      (x_list, y_list) tuple/list of two sequences or a DataFrame with 'x' and 'y'
      columns. All sets must contain the same number of points so the per-set
      labels can be averaged element-wise.
    - n_clusters (int): Number of clusters to form, default to 2
    - random_state (int): Initial random state of k-means, default to 0

    Returns:
    tuple: The overall labels and centroids as numpy arrays.
        - overall_labels (np.ndarray): Integer array where each element is the
          averaged cluster label assigned to each data point.
        - overall_centroids (np.ndarray): Array containing the averaged coordinates
          of the cluster centers across all data sets.
    """
    if not data_sets:
        raise ValueError("data_sets must contain at least one data set")

    all_labels = []
    all_centroids = []

    for i, data_set in enumerate(data_sets):
        if isinstance(data_set, pd.DataFrame):
            df = pd.DataFrame({'x': data_set['x'], 'y': data_set['y']})
        elif isinstance(data_set, (tuple, list)) and len(data_set) == 2:
            x, y = data_set
            if len(x) != len(y):
                raise ValueError(
                    f"Data set {i}: 'x' and 'y' must have the same length"
                )
            df = pd.DataFrame({'x': x, 'y': y})
        else:
            raise ValueError(
                "Each data set must be a (x, y) pair of sequences or a DataFrame "
                "with 'x' and 'y' columns"
            )

        kmeans = KMeans(n_clusters=n_clusters, n_init=10, random_state=random_state)
        kmeans.fit(df)
        all_labels.append(np.asarray(kmeans.labels_, dtype=float))
        all_centroids.append(np.asarray(kmeans.cluster_centers_, dtype=float))

    label_lengths = {len(lab) for lab in all_labels}
    if len(label_lengths) > 1:
        raise ValueError("All data sets must have the same number of points "
                         "to average the labels")

    overall_labels = np.round(np.mean(all_labels, axis=0)).astype(int)
    overall_centroids = np.mean(all_centroids, axis=0)

    return overall_labels, overall_centroids

